147			{Kind: OpLoad, CargoID: "G3", Target: "C2"},
148			{Kind: OpLoad, CargoID: "G2", Target: "C1"},
149			{Kind: OpLoad, CargoID: "G1", Target: "C1"},
150		}
151		se := submitExpectReject(t, r, "  adj-1  ", ops)
